#include "core/countdown_manager.h"
#include "core/pomodoro_timer.h"
#include "core/study_record.h"
#include "data/storage.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define YANTU_WATCH_VERSION "1.0.0"

/* Screen resolution for SF32LB52 LCD */
#define LCD_H_RES          240
#define LCD_V_RES          240

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* Application state */
struct yantu_app_s
{
  lv_obj_t *scr_main;        /* Main screen */
  lv_obj_t *scr_countdown;   /* Countdown screen */
  lv_obj_t *scr_pomodoro;    /* Pomodoro timer screen */
  lv_obj_t *scr_vocabulary;  /* Vocabulary screen */
  lv_obj_t *scr_audio;       /* Audio player screen */
  lv_obj_t *scr_reminder;    /* Reminder screen */
  lv_obj_t *scr_study_plan;  /* Study plan screen */
  lv_obj_t *scr_settings;    /* Settings screen */
  lv_obj_t *current_scr;     /* Currently displayed screen */
  bool initialized;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct yantu_app_s g_yantu_app;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void lvgl_tick_task(lv_task_t *task)
{
  lv_tick_inc(1);
}

static void lvgl_init(void)
{
  lv_init();

  /* Initialize LVGL display driver for SF32LB52 LCD */
  lv_disp_drv_t disp_drv;
  lv_disp_drv_init(&disp_drv);
  /* Display driver will be configured by the board's LCD initialization */
  lv_disp_drv_register(&disp_drv);

  /* Initialize LVGL input driver (touchscreen) */
  lv_indev_drv_t indev_drv;
  lv_indev_drv_init(&indev_drv);
  indev_drv.type = LV_INDEV_TYPE_POINTER;
  lv_indev_drv_register(&indev_drv);

  /* Create a periodic tick timer for LVGL */
  lv_task_create(lvgl_tick_task, 1, LV_TASK_PRIO_LOWEST, NULL);
}

static void app_init_modules(void)
{
  /* Initialize data storage layer */
  storage_init();

  /* Initialize core modules */
  countdown_init();
  pomodoro_init();
  study_record_init();

  /* Load saved settings */
  /* TODO: Load settings from Flash */
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  printf("YanTu Watch v%s starting...\n", YANTU_WATCH_VERSION);

  /* Initialize LVGL */
  lvgl_init();

  /* Initialize application modules */
  app_init_modules();

  /* Create the main screen */
  g_yantu_app.scr_main = ui_main_create();
  g_yantu_app.current_scr = g_yantu_app.scr_main;
  lv_scr_load(g_yantu_app.scr_main);

  printf("YanTu Watch initialized successfully!\n");

  /* Main loop - LVGL will handle the event loop */
  while (1)
  {
    lv_task_handler();
    usleep(5000); /* 5ms delay */
  }

  return 0;
