{"content": "/****************************************************************************
 * apps/examples/yantu_watch/core/countdown_manager.c
 *
 * 考研倒计时管理模块
 * - 基于 RTC 实时计算距离考研日期的时间
 * - 支持自定义考试日期，持久化到 Flash
 ****************************************************************************/

#include <nuttx/config.h>
#include <time.h>
#include "countdown_manager.h"
#include "database.h"

#define KEY_EXAM_YEAR  "exam_year"
#define KEY_EXAM_MONTH "exam_month"
#define KEY_EXAM_DAY   "exam_day"

/* Default exam date: 2026-12-19 (全国硕士研究生招生考试) */
#define DEFAULT_YEAR  2026
#define DEFAULT_MONTH 12
#define DEFAULT_DAY   19

static int g_exam_year;
static int g_exam_month;
static int g_exam_day;

int countdown_init(void)
{
  /* Load saved exam date from Flash, fallback to default */
  g_exam_year = db_get_int(KEY_EXAM_YEAR, DEFAULT_YEAR);
  g_exam_month = db_get_int(KEY_EXAM_MONTH, DEFAULT_MONTH);
  g_exam_day = db_get_int(KEY_EXAM_DAY, DEFAULT_DAY);
  return 0;
}

int countdown_get_days_remaining(void)
{
  time_t now;
  struct tm exam_tm = { 0 };
  time(&now);

  exam_tm.tm_year = g_exam_year - 1900;
  exam_tm.tm_mon  = g_exam_month - 1;
  exam_tm.tm_mday = g_exam_day;
  exam_tm.tm_hour = 0;
  exam_tm.tm_min  = 0;
  exam_tm.tm_sec  = 0;

  time_t exam_time = mktime(&exam_tm);
  double diff = difftime(exam_time, now);
  return (diff > 0) ? (int)(diff / 86400) : 0;
}

void countdown_get_time_remaining(int *days, int *hours, int *mins, int *secs)
{
  time_t now;
  struct tm exam_tm = { 0 };
  time(&now);

  exam_tm.tm_year = g_exam_year - 1900;
  exam_tm.tm_mon  = g_exam_month - 1;
  exam_tm.tm_mday = g_exam_day;
  exam_tm.tm_hour = 0;
  exam_tm.tm_min  = 0;
  exam_tm.tm_sec  = 0;

  time_t exam_time = mktime(&exam_tm);
  double diff = difftime(exam_time, now);
  if (diff > 0)
    {
      *days  = (int)(diff / 86400);
      *hours = (int)((diff - *days * 86400) / 3600);
      *mins  = (int)((diff - *days * 86400 - *hours * 3600) / 60);
      *secs  = (int)(diff - *days * 86400 - *hours * 3600 - *mins * 60);
    }
  else
    {
      *days  = 0;
      *hours = 0;
      *mins  = 0;
      *secs  = 0;
    }
}

void countdown_set_exam_date(int year, int month, int day)
{
  g_exam_year  = year;
  g_exam_month = month;
  g_exam_day   = day;

  /* Persist to Flash */
  db_set_int(KEY_EXAM_YEAR, year);
  db_set_int(KEY_EXAM_MONTH, month);
  db_set_int(KEY_EXAM_DAY, day);
}

void countdown_get_exam_date(int *year, int *month, int *day)
{
  *year  = g_exam_year;
  *month = g_exam_month;
  *day   = g_exam_day;
}", "file_path": "/data/contest2026_201_chaojizhuzhuxia/app/yantu_watch/core/countdown_manager.c"}

{"content": "/****************************************************************************
 * apps/examples/yantu_watch/core/study_record.c
 *
 * 学习时长统计模块
 * - 每日学习时长记录，精度到分钟
 * - 持久化到 Flash，支持周/月统计
 ****************************************************************************/

#include <nuttx/config.h>
#include <time.h>
#include <string.h>
#include <stdio.h>
#include "study_record.h"
#include "storage.h"
#include "json_parser.h"
#include <cJSON.h>

#define MAX_DAYS 365

#define RECORD_FILE "study_record.json"

static int g_today_minutes = 0;
static int g_total_minutes = 0;
static int g_total_days   = 0;

/* Load record from Flash */
static int load_record(void)
{
  cJSON *root = NULL;
  if (json_parse_file(RECORD_FILE, &root) != 0)
    return -1;

  g_today_minutes = json_get_int(root, "today_minutes", 0);
  g_total_minutes = json_get_int(root, "total_minutes", 0);
  g_total_days    = json_get_int(root, "total_days", 0);

  cJSON_Delete(root);
  return 0;
}

/* Save record to Flash */
static int save_record(void)
{
  cJSON *root = cJSON_CreateObject();
  if (!root) return -1;

  cJSON_AddNumberToObject(root, "today_minutes", g_today_minutes);
  cJSON_AddNumberToObject(root, "total_minutes", g_total_minutes);
  cJSON_AddNumberToObject(root, "total_days",    g_total_days);

  int ret = json_save_file(RECORD_FILE, root);
  cJSON_Delete(root);
  return ret;
}

int study_record_init(void)
{
  /* Try to load existing record */
  if (load_record() != 0)
    {
      /* First run: create default record */
      g_today_minutes = 0;
      g_total_minutes = 0;
      g_total_days    = 0;
      save_record();
    }
  return 0;
}

int study_record_add_minutes(int minutes)
{
  g_today_minutes += minutes;
  g_total_minutes += minutes;

  /* If this is the first study of the day, increment day count */
  if (g_today_minutes <= minutes)
    g_total_days++;

  return save_record();
}

int study_record_get_today_minutes(void)
{
  return g_today_minutes;
}

int study_record_get_week_data(int *data, int *count)
{
  /* TODO: Load detailed daily records from week log */
  *count = 7;
  memset(data, 0, 7 * sizeof(int));
  data[6] = g_today_minutes; /* Today is the last day of the week view */
  return 0;
}

int study_record_get_month_data(int *data, int *count)
{
  *count = 30;
  memset(data, 0, 30 * sizeof(int));
  data[29] = g_today_minutes;
  return 0;
}

int study_record_get_total_days(void)
{
  return g_total_days;
}

int study_record_get_total_minutes(void)
{
  return g_total_minutes;
}", "file_path": "/data/contest2026_201_chaojizhuzhuxia/app/yantu_watch/core/study_record.c"}

